// Build-time only: screenshots are never generated by the showcase server.
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { promises as fs } from 'node:fs';
import http from 'node:http';
import path from 'node:path';
import { chromium } from 'playwright';
import { listTemplateDirectories, rootDir, srcDir } from './showcase-lib.mjs';
import { THUMBNAIL_DIR, THUMBNAIL_FORMATS, THUMBNAIL_WIDTHS } from './thumbnail-lib.mjs';

const args = process.argv.slice(2);
const changed = args.includes('--changed');
const slugs = args.filter(arg => arg !== '--changed');
if (slugs.some(arg => arg.startsWith('-'))) throw new Error('Usage: capture-thumbnails.mjs [--changed] [slug ...]');
const templates = await listTemplateDirectories();
for (const slug of slugs) if (!templates.some(t => t.slug === slug)) throw new Error(`Unknown template: ${slug}`);
const selected = templates.filter(t => !slugs.length || slugs.includes(t.slug));
const output = path.join(rootDir, THUMBNAIL_DIR);
const manifestPath = path.join(output, 'manifest.json');
await fs.mkdir(output, { recursive: true });
let manifest = {};
try { manifest = JSON.parse(await fs.readFile(manifestPath, 'utf8')); } catch (error) { if (error.code !== 'ENOENT') throw error; }

// Hash all files in the template, plus the capture implementation and encoder settings.
async function hashDirectory(dir, hash) {
  for (const entry of (await fs.readdir(dir, { withFileTypes: true })).sort((a, b) => a.name.localeCompare(b.name))) {
    const file = path.join(dir, entry.name);
    hash.update(path.relative(rootDir, file));
    if (entry.isDirectory()) await hashDirectory(file, hash);
    else if (entry.isFile()) hash.update(await fs.readFile(file));
  }
}
async function fingerprint(slug) {
  const hash = createHash('sha256');
  await hashDirectory(path.join(srcDir, slug), hash);
  for (const file of ['scripts/capture-thumbnails.mjs', 'scripts/thumbnail-lib.mjs', 'package-lock.json']) hash.update(await fs.readFile(path.join(rootDir, file)));
  return hash.digest('hex');
}
async function outputsExist(slug) {
  try {
    await Promise.all(THUMBNAIL_WIDTHS.flatMap(width => Object.keys(THUMBNAIL_FORMATS).map(ext => fs.access(path.join(output, `${slug}-${width}.${ext}`)))));
    return true;
  } catch { return false; }
}
const pending = [];
for (const template of selected) {
  const hash = await fingerprint(template.slug);
  if (changed && manifest[template.slug] === hash && await outputsExist(template.slug)) console.log(`[thumbnails] ${template.slug}: cached`);
  else pending.push({ ...template, hash });
}
if (pending.length) {
  // Serve only template files, on an ephemeral loopback port; no app or external services are started.
  const server = http.createServer(async (request, response) => {
    try {
      const url = new URL(request.url, 'http://localhost');
      const file = path.resolve(rootDir, `.${decodeURIComponent(url.pathname)}`);
      if (!file.startsWith(srcDir + path.sep)) throw new Error('outside src');
      const data = await fs.readFile(file);
      const mime = { '.html': 'text/html', '.css': 'text/css', '.js': 'text/javascript', '.svg': 'image/svg+xml', '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.webp': 'image/webp', '.woff': 'font/woff', '.woff2': 'font/woff2' };
      response.writeHead(200, { 'content-type': mime[path.extname(file).toLowerCase()] || 'application/octet-stream' });
      response.end(data);
    } catch { response.writeHead(404); response.end(); }
  });
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  let browser;
  const failures = [];
  try {
    browser = await chromium.launch({ headless: true, ...(process.env.CHROMIUM ? { executablePath: process.env.CHROMIUM } : {}) });
    for (const { slug, href, hash } of pending) {
      let error;
      for (let attempt = 1; attempt <= 2; attempt++) {
        const context = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1, colorScheme: 'light', reducedMotion: 'reduce', serviceWorkers: 'block' });
        try {
          // External scripts, XHR, forms and navigation must never contact integrations.
          await context.route('**/*', route => {
            const request = route.request();
            const url = new URL(request.url());
            const local = url.origin === `http://127.0.0.1:${server.address().port}`;
            if (request.method() !== 'GET' || (!local && !['image', 'font', 'stylesheet'].includes(request.resourceType()))) return route.abort();
            return route.continue();
          });
          const page = await context.newPage();
          page.setDefaultTimeout(15000);
          const response = await page.goto(`http://127.0.0.1:${server.address().port}${href}`, { waitUntil: 'load', timeout: 20000 });
          if (!response?.ok()) throw new Error(`HTTP ${response?.status()}`);
          await page.evaluate(async () => {
            const deadline = new Promise((_, reject) => setTimeout(() => reject(new Error('Resource timeout')), 12000));
            await Promise.race([(async () => {
            await document.fonts.ready;
            const images = [...document.images].filter(img => { const r = img.getBoundingClientRect(); return r.top < innerHeight && r.bottom > 0 && r.left < innerWidth && r.right > 0; });
            await Promise.all(images.map(img => img.decode().catch(() => { throw new Error(`Image failed: ${img.currentSrc || img.src}`); })));
            if (!document.body || document.body.innerText.trim().length < 20) throw new Error('Empty page');
            })(), deadline]);
          });
          const png = await page.screenshot({ animations: 'disabled', timeout: 15000 });
          for (const width of THUMBNAIL_WIDTHS) for (const [ext, options] of Object.entries(THUMBNAIL_FORMATS)) {
            const target = path.join(output, `${slug}-${width}.${ext}`);
            const temp = `${target}.tmp.${ext}`;
            execFileSync('convert', ['png:-', '-resize', `${width}x`, '-strip', ...options, temp], { input: png, timeout: 30000 });
            await fs.rename(temp, target);
          }
          manifest[slug] = hash;
          await fs.writeFile(manifestPath, JSON.stringify(manifest, null, 2) + '\n');
          console.log(`[thumbnails] ${slug}: generated`);
          error = null;
          break;
        } catch (err) { error = err; console.error(`[thumbnails] ${slug}: attempt ${attempt} failed: ${err.message}`); }
        finally { await context.close(); }
      }
      if (error) failures.push(slug);
    }
  } finally { await browser?.close(); await new Promise(resolve => server.close(resolve)); }
  if (failures.length) throw new Error(`Thumbnail generation failed: ${failures.join(', ')}`);
}
